import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from './components/Layout';

function CreateJob() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    type: 'CDI',
    contract: 'Temps plein',
    location: ''
  });

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/jobs`, {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json' 
        },
        body: JSON.stringify(formData)
      });

      if (response.ok) {
        alert("Offre créée avec succès !");
        navigate('/');
      } else {
        alert("Erreur lors de la création de l'offre");
      }
    } catch (error) {
      console.error("Erreur serveur :", error);
      alert("Erreur lors de la connexion au serveur");
    }
  };

  return (
    <Layout>
      <div className="create-job-container">
        <h2>Créer une nouvelle offre</h2>
        <form onSubmit={handleSubmit}>
          <div>
            <label>Titre du poste</label>
            <input 
              type="text" 
              value={formData.title}
              onChange={(e) => setFormData({...formData, title: e.target.value})}
              required
            />
          </div>
          <div>
            <label>Description</label>
            <textarea 
              value={formData.description}
              onChange={(e) => setFormData({...formData, description: e.target.value})}
              required
            />
          </div>
          <div>
            <label>Type</label>
            <select value={formData.type} onChange={(e) => setFormData({...formData, type: e.target.value})}>
              <option value="CDI">CDI</option>
              <option value="CDD">CDD</option>
              <option value="Stage">Stage</option>
            </select>
          </div>
          <button type="submit" className="btn-primary">Publier l'offre</button>
          <button type="button" onClick={() => navigate('/')}>Annuler</button>
        </form>
      </div>
    </Layout>
  );
}

export default CreateJob;
